/*
 * 共享「气质海报」生成器（零依赖、纯前端）
 * ----------------------------------------------------------------
 * 把一份审美画像（8 轴向量 + 气质词 + 框架主/次）渲染成一张**确定性**的
 * SVG 配图：同一人不随刷新变化。用于：
 *   1) 分享卡片配图（share.html 顶部那张视觉）
 *   2) 美化报告封面（index.html 导出美化报告）
 *
 * 全程不消耗任何付费出图额度，保证每张分享卡都有视觉、可被下载为 PNG。
 *
 * 对外暴露 window.AestheticPoster：
 *   renderPosterSVG(opts) -> <svg ...>...</svg> 字符串
 *   svgToPng(svg, w, h, cb) -> cb(Blob|null)
 */
(function () {
  'use strict';

  // ---------- 7 套精选低饱和优雅色板：由向量确定性挑选 ----------
  // 每套含 light / dark 两版，dark 用深底 + 提亮主色，保证同一张气质海报在两种主题下都耐看。
  var PALETTES = [
    { name: '雾玫瑰', bg1: '#f7e9ef', bg2: '#f1dbe6', card: '#fffafc', accent: '#c0508a', ink: '#3a2b34', sub: '#9a7c8a', ring: '#e7c6d6',
      dark: { bg1: '#2a1f28', bg2: '#1f1722', card: '#34242e', accent: '#ff8fc0', ink: '#f3e7ee', sub: '#c9a6ba', ring: '#5a3a4c' } },
    { name: '鼠尾草', bg1: '#e9f1ea', bg2: '#d8e9df', card: '#fbfdfb', accent: '#2e7d5b', ink: '#26342e', sub: '#6f8a7c', ring: '#bfe0cf',
      dark: { bg1: '#1b2620', bg2: '#14201a', card: '#20302a', accent: '#6fe0a8', ink: '#e6f3ec', sub: '#a6c9b8', ring: '#35503f' } },
    { name: '薰衣草', bg1: '#efeafb', bg2: '#e1d9f6', card: '#fcfbff', accent: '#6a4fd0', ink: '#2e2742', sub: '#7e74a0', ring: '#cfc3f0',
      dark: { bg1: '#211c33', bg2: '#181428', card: '#2a2440', accent: '#b49cff', ink: '#ece8fb', sub: '#b9aede', ring: '#473c66' } },
    { name: '雾霾蓝', bg1: '#e9eef5', bg2: '#d9e4ef', card: '#fbfcfe', accent: '#3f6ea8', ink: '#28323d', sub: '#6f8298', ring: '#bccfe6',
      dark: { bg1: '#192230', bg2: '#131b28', card: '#1f2a3a', accent: '#7fb0e8', ink: '#e7eef7', sub: '#a6bcd4', ring: '#2e3e54' } },
    { name: '沙金',   bg1: '#f6efe2', bg2: '#efe3cd', card: '#fffdf8', accent: '#b08a3e', ink: '#3a3326', sub: '#9a8a6c', ring: '#e2cfa6',
      dark: { bg1: '#26211a', bg2: '#1d1812', card: '#2e281e', accent: '#e6c277', ink: '#f3ece0', sub: '#c9b894', ring: '#4d422e' } },
    { name: '青瓷',   bg1: '#e6f3f1', bg2: '#d2eae5', card: '#fafdfc', accent: '#1f8a86', ink: '#243a39', sub: '#6a8a88', ring: '#b6ddd8',
      dark: { bg1: '#15272a', bg2: '#0f1d20', card: '#1b2e30', accent: '#5fd6cf', ink: '#e4f4f2', sub: '#9fcac6', ring: '#2c4a48' } },
  { name: '梅紫',   bg1: '#f3e9f2', bg2: '#ead8ec', card: '#fdfbff', accent: '#8a4f9a', ink: '#33253a', sub: '#8a7490', ring: '#d7bce0',
      dark: { bg1: '#241a28', bg2: '#1a121f', card: '#2c2030', accent: '#c98fdc', ink: '#efe6f3', sub: '#c2a6cc', ring: '#4a3452' } }
  ];

  // 由 canvas-design 生成的艺术底纹（内联 data URI，确保导出 PNG 时也能保留）
  var BG_ART = {
  rose: 'data:image/png;base64,',
  sage: 'data:image/png;base64,',
  plum: 'data:image/png;base64,'
};

  function getDATA() {
    return (typeof window !== 'undefined' && window.AESTHETIC_DATA) || null;
  }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
    });
  }

  // 由向量确定性挑色板：同一人稳定，不同气质易区分。theme='dark' 时返回该色板的暗色变体。
  function pickPalette(vec, theme) {
    var dims = (getDATA() && getDATA().dims && getDATA().dims.dimensions) || [];
    var sum = 0, n = 0, hash = 0;
    if (vec) {
      for (var k in vec) {
        var v = Number(vec[k]) || 0;
        sum += v; n++;
        hash += Math.round(v * 1000);
      }
    }
    var avg = n ? sum / n : 0;
    var idx = Math.abs(hash + Math.round(avg * 137)) % PALETTES.length;
    var pal = PALETTES[idx];
    return (theme === 'dark' && pal.dark) ? pal.dark : pal;
  }
  // 由 opts 统一解析主题（'dark' | 其他视为浅色），供三套版式共用
  function pickTheme(opts) { return (opts && opts.theme === 'dark') ? 'dark' : 'light'; }

  // 由调色板索引确定性选一张 canvas-design 艺术底纹（3 个家族）
  var PALETTE_TO_ART = ['rose', 'sage', 'plum', 'plum', 'rose', 'sage', 'plum'];
  function pickArt(vec) {
    var sum = 0, n = 0, hash = 0;
    if (vec) {
      for (var k in vec) {
        var v = Number(vec[k]) || 0;
        sum += v; n++;
        hash += Math.round(v * 1000);
      }
    }
    var avg = n ? sum / n : 0;
    var idx = Math.abs(hash + Math.round(avg * 137)) % PALETTES.length;
    return PALETTE_TO_ART[idx] || 'plum';
  }

  // 把艺术底纹作为低透明度背景层嵌入 SVG，再加半透明遮罩保证文字可读
  function bgArtBlock(vec, W, H, scrimColor, scrimOp) {
    var key = pickArt(vec);
    var src = (typeof BG_ART !== 'undefined' && BG_ART && BG_ART[key]) || '';
    if (!src) return '';
    return '<image href="' + src + '" x="0" y="0" width="' + W + '" height="' + H + '" preserveAspectRatio="xMidYMid slice" opacity="0.48"/>' +
      '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="' + scrimColor + '" opacity="' + scrimOp + '"/>';
  }

  // 一段文字的估算像素宽（用于 SVG 里手摆元素）。CJK 约为 1*字号、Latin 约为 0.55；
  // 取 0.8 折中，避免中文标签溢出药丸/雷达标签框。
  function textW(t, fs) { return String(t).length * fs * 0.8 + 4; }

  // 框架名与主/次结果的可读标签（三种版式共用，故提到模块作用域）
  function fwName(fwId) {
    var DATA = getDATA();
    return (DATA && DATA.bank && DATA.bank.frameworks && DATA.bank.frameworks[fwId] && DATA.bank.frameworks[fwId].name) || fwId;
  }
  function resLabel(fwId, key) {
    if (!key) return '—';
    var DATA = getDATA();
    if (fwId === 'astro') {
      var m = String(key).match(/^(sun|moon|asc)_(.+)$/);
      if (m) {
        var sg = DATA && DATA.bank && DATA.bank.signs && DATA.bank.signs[m[2]];
        return ({ sun: '太阳', moon: '月亮', asc: '上升' }[m[1]]) + '·' + (sg ? sg.label : m[2]);
      }
    }
    var fw = DATA && DATA.bank && DATA.bank.frameworks && DATA.bank.frameworks[fwId];
    if (fw && fw.results && fw.results[key] && fw.results[key].label) return fw.results[key].label;
    return key;
  }

  // 按估算宽度把长文折成若干行，最多 maxLines 行，末行超长则省略
  function wrapText(text, fs, maxW, maxLines) {
    var s = String(text == null ? '' : text).replace(/\s+/g, ' ').trim();
    if (!s) return [];
    var lines = [], cur = '';
    for (var i = 0; i < s.length; i++) {
      if (textW(cur + s[i], fs) > maxW && cur) {
        lines.push(cur); cur = '';
        if (lines.length >= maxLines) break;
      }
      cur += s[i];
    }
    if (lines.length < maxLines && cur) lines.push(cur);
    // 内容没排完 → 末行加省略号
    var used = lines.join('').length;
    if (used < s.length && lines.length) {
      var last = lines[lines.length - 1];
      lines[lines.length - 1] = last.slice(0, Math.max(1, last.length - 1)) + '…';
    }
    return lines;
  }

  // 左对齐药丸，返回 { svg, w }，便于横排布局时累加 x
  function pillLeft(x, y, text, fill, fg, fs) {
    var w = textW(text, fs) + 24, h = fs + 16;
    return {
      w: w,
      svg: '<g><rect x="' + x.toFixed(1) + '" y="' + (y - h / 2).toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + h + '" rx="' + (h / 2) + '" fill="' + fill + '"/>' +
        '<text x="' + (x + w / 2).toFixed(1) + '" y="' + (y + fs * 0.34).toFixed(1) + '" font-size="' + fs + '" fill="' + fg + '" text-anchor="middle" font-family="-apple-system,Helvetica,Arial,sans-serif">' + esc(text) + '</text></g>'
    };
  }

  // 画一个圆角药丸（标签 / 框架）
  function pill(cx, y, text, fill, fg, fs) {
    var w = textW(text, fs) + 24, h = fs + 16, x = cx - w / 2;
    return '<g><rect x="' + x.toFixed(1) + '" y="' + (y - h / 2).toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + h + '" rx="' + (h / 2) + '" fill="' + fill + '"/>' +
      '<text x="' + cx.toFixed(1) + '" y="' + (y + fs * 0.34).toFixed(1) + '" font-size="' + fs + '" fill="' + fg + '" text-anchor="middle" font-family="-apple-system,Helvetica,Arial,sans-serif">' + esc(text) + '</text></g>';
  }

  // 8 轴雷达图（网格 + 轴线 + 正向标签 + 数据多边形）。三种版式共用，只是尺寸不同。
  function radar(cx, cy, R, dims, vec, pal, labelFs) {
    var out = '', N = dims.length || 8;
    [0.25, 0.5, 0.75, 1].forEach(function (f) {
      var pts = dims.map(function (dim, i) {
        var ang = -Math.PI / 2 + i * 2 * Math.PI / N;
        return (cx + R * f * Math.cos(ang)).toFixed(1) + ',' + (cy + R * f * Math.sin(ang)).toFixed(1);
      }).join(' ');
      out += '<polygon points="' + pts + '" fill="none" stroke="' + pal.sub + '" stroke-opacity="0.22" stroke-width="1"/>';
    });
    dims.forEach(function (dim, i) {
      var ang = -Math.PI / 2 + i * 2 * Math.PI / N;
      var x = cx + R * Math.cos(ang), y = cy + R * Math.sin(ang);
      out += '<line x1="' + cx + '" y1="' + cy + '" x2="' + x.toFixed(1) + '" y2="' + y.toFixed(1) + '" stroke="' + pal.sub + '" stroke-opacity="0.28" stroke-width="1"/>';
      var lr = R + labelFs * 1.85;
      var lx = cx + lr * Math.cos(ang), ly = cy + lr * Math.sin(ang);
      var anchor = Math.abs(Math.cos(ang)) < 0.3 ? 'middle' : (Math.cos(ang) > 0 ? 'start' : 'end');
      var ty = ly + (Math.sin(ang) > 0.5 ? labelFs * 1.08 : (Math.sin(ang) < -0.5 ? -labelFs * 0.46 : labelFs * 0.31));
      out += '<text x="' + lx.toFixed(1) + '" y="' + ty.toFixed(1) + '" font-size="' + labelFs + '" fill="' + pal.ink + '" text-anchor="' + anchor + '">' + esc(dim.posLabel || dim.id) + '</text>';
    });
    var ppts = dims.map(function (dim, i) {
      var v = Math.max(-1, Math.min(1, Number(vec[dim.id]) || 0));
      var ang = -Math.PI / 2 + i * 2 * Math.PI / N;
      var r = R * (v + 1) / 2;
      return [cx + r * Math.cos(ang), cy + r * Math.sin(ang)];
    });
    out += '<polygon points="' + ppts.map(function (p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' ')
      + '" fill="' + pal.accent + '" fill-opacity="0.30" stroke="' + pal.accent + '" stroke-width="' + (R > 190 ? 3 : 2.5) + '" stroke-linejoin="round"/>';
    ppts.forEach(function (p) {
      out += '<circle cx="' + p[0].toFixed(1) + '" cy="' + p[1].toFixed(1) + '" r="' + (R > 190 ? 4.2 : 3.6) + '" fill="' + pal.accent + '"/>';
    });
    return out;
  }

  function renderPosterSVG(opts) {
    opts = opts || {};
    var vec = opts.vector || {};
    var title = opts.title || '我的神性测评';
    var mood = opts.mood || [];
    var results = opts.results || {};
    var dims = (getDATA() && getDATA().dims && getDATA().dims.dimensions) || [];

    var theme = pickTheme(opts);
    var pal = pickPalette(vec, theme);
    var W = 800, H = 1130;
    var cx = W / 2, cy = 470, R = 170;

    // ---- 背景 + 顶部品牌 ----
    var out = '';
    out += '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '" font-family="-apple-system,Helvetica,Arial,sans-serif">';
    out += '<defs><linearGradient id="bg" x1="0" y1="0" x2="0.4" y2="1">' +
      '<stop offset="0" stop-color="' + pal.bg1 + '"/><stop offset="1" stop-color="' + pal.bg2 + '"/></linearGradient></defs>';
    out += '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="url(#bg)"/>';
    out += bgArtBlock(vec, W, H, pal.bg1, theme === 'dark' ? 0.82 : 0.45);
    out += '<text x="' + cx + '" y="62" font-size="15" fill="' + pal.sub + '" text-anchor="middle" letter-spacing="2">AI 审美系统 · 神性测评</text>';

    // ---- 标题（截断保护）----
    var t = String(title).replace(/\s+/g, ' ');
    if (t.length > 20) t = t.slice(0, 19) + '…';
    out += '<text x="' + cx + '" y="108" font-size="33" font-weight="700" fill="' + pal.ink + '" text-anchor="middle">' + esc(t) + '</text>';

    // ---- 气质词药丸（居中排一行，超长省略）----
    var moodShow = mood.slice(0, 4);
    var mfs = 16, gap = 12, mw = moodShow.reduce(function (s, m) { return s + textW(m, mfs) + 24 + gap; }, 0) - gap;
    var mx = cx - mw / 2, my = 152;
    moodShow.forEach(function (m) {
      var w = textW(m, mfs) + 24;
      out += pill(mx + w / 2, my, m, pal.ring, pal.accent, mfs);
      mx += w + gap;
    });

    // ---- 雷达图 ----
    out += radar(cx, cy, R, dims, vec, pal, 13);

    // ---- 框架主/次药丸（居中两行）----
    var fws = Object.keys(results).slice(0, 4);
    var fy = 740, fgap = 12, ffs = 15;
    var rowStep = ffs + 16 + fgap;
    fws.forEach(function (fwId, i) {
      var r = results[fwId] || {};
      var txt = fwName(fwId) + '：' + resLabel(fwId, r.primary) + ' / ' + resLabel(fwId, r.secondary);
      if (txt.length > 18) txt = txt.slice(0, 17) + '…';
      var row = i;
      out += pill(cx, fy + row * rowStep, txt, pal.card, pal.accent, ffs);
    });
    // 说明始终排在最后一个框架药丸下方，避免两者文字重叠
    var lastFy = fy + (fws.length - 1) * rowStep;
    var ey = lastFy + (ffs + 16 + fgap) + 18;

    // ---- 说明（截断 3 行，按 CJK 宽度估算换行）----
    var exp = String(opts.explanation || '').replace(/\s+/g, ' ').trim();
    if (exp) {
      var cw = 13 * 0.85 + 0.2; // 单字近似宽度（CJK 偏宽，留余量）
      var maxChars = Math.floor((W - 150) / cw);
      var lines = [], cur = '';
      for (var i2 = 0; i2 < exp.length; i2++) {
        var ch = exp[i2];
        if (cur.length >= maxChars && cur) { lines.push(cur); cur = ''; }
        cur += ch;
        if (lines.length >= 3) break;
      }
      if (lines.length < 3 && cur) lines.push(cur);
      if (lines.length === 3 && lines[2].length >= maxChars) lines[2] = lines[2].slice(0, maxChars - 1) + '…';
      lines.forEach(function (ln, idx) {
        out += '<text x="' + cx + '" y="' + (ey + idx * 22) + '" font-size="13" fill="' + pal.sub + '" text-anchor="middle">' + esc(ln) + '</text>';
      });
    }

    // ---- 底部品牌 ----
    out += '<line x1="120" y1="' + (H - 70) + '" x2="' + (W - 120) + '" y2="' + (H - 70) + '" stroke="' + pal.sub + '" stroke-opacity="0.3" stroke-width="1"/>';
    out += '<text x="' + cx + '" y="' + (H - 44) + '" font-size="14" fill="' + pal.sub + '" text-anchor="middle">扫码 / 访问体验你的神性测评 · 这是一张公开气质卡</text>';
    out += '</svg>';
    return out;
  }

  /*
   * OG 社交预览卡：1200×630 横版（各社交平台 og:image 的通用比例）
   * ----------------------------------------------------------------
   * 竖版海报（800×1130）贴到微信/飞书/Telegram 的链接预览里会被裁成一条，
   * 所以社交抓图必须单独出一张横版：左侧文案、右侧雷达，信息在缩略图尺寸下仍可辨。
   */
  function renderOGCardSVG(opts) {
    opts = opts || {};
    var vec = opts.vector || {};
    var mood = opts.mood || [];
    var results = opts.results || {};
    var dims = (getDATA() && getDATA().dims && getDATA().dims.dimensions) || [];
    var theme = pickTheme(opts);
    var pal = pickPalette(vec, theme);
    var W = 1200, H = 630;
    var x0 = 74, colW = 600;

    var out = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '" font-family="-apple-system,Helvetica,Arial,sans-serif">';
    out += '<defs><linearGradient id="ogbg" x1="0" y1="0" x2="1" y2="1">' +
      '<stop offset="0" stop-color="' + pal.bg1 + '"/><stop offset="1" stop-color="' + pal.bg2 + '"/></linearGradient></defs>';
    // 主视觉：优先用真实 AI 出图（OG 预览图主视觉用出图），叠加暗化渐变保证文字可读；
    // 无出图时回退到气质渐变海报。
    var imgOK = opts.image && (/^data:image/.test(opts.image) || /^(https?:)/.test(opts.image));
    if (imgOK) {
      out += '<image href="' + esc(opts.image) + '" xmlns:xlink="http://www.w3.org/1999/xlink" xlink:href="' + esc(opts.image) + '" x="0" y="0" width="' + W + '" height="' + H + '" preserveAspectRatio="xMidYMid slice"/>';
      out += '<defs><linearGradient id="ogvig" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="rgba(8,6,16,0.72)"/><stop offset="0.55" stop-color="rgba(8,6,16,0.18)"/><stop offset="1" stop-color="rgba(8,6,16,0)"/></linearGradient></defs>';
      out += '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="url(#ogvig)"/>';
      out += bgArtBlock(vec, W, H, pal.bg1, 0.16);
    } else {
      out += '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="url(#ogbg)"/>';
      out += bgArtBlock(vec, W, H, pal.bg1, theme === 'dark' ? 0.78 : 0.35);
    }

    // 右侧雷达（先画，避免压住左侧文案）
    out += radar(930, 315, 190, dims, vec, pal, 15);

    // 左栏：品牌 → 标题 → 气质词 → 框架
    out += '<text x="' + x0 + '" y="92" font-size="18" fill="' + pal.sub + '" letter-spacing="3">AI 审美系统 · 神性测评</text>';
    var tLines = wrapText(opts.title || '我的神性测评', 44, colW, 2);
    var y = 158;
    tLines.forEach(function (ln) {
      out += '<text x="' + x0 + '" y="' + y + '" font-size="44" font-weight="700" fill="' + pal.ink + '">' + esc(ln) + '</text>';
      y += 56;
    });
    y += 6;

    // 气质词：一行排不下就截断，宁可少几个也不换行挤压
    var mfs = 19, mx = x0;
    mood.slice(0, 4).forEach(function (m) {
      var p = pillLeft(mx, y + mfs, m, pal.ring, pal.accent, mfs);
      if (mx + p.w > x0 + colW) return;
      out += p.svg; mx += p.w + 10;
    });
    y += mfs + 44;

    // 框架主/次：最多 3 条，每条一行
    var ffs = 17;
    Object.keys(results).slice(0, 3).forEach(function (fwId) {
      var r = results[fwId] || {};
      var txt = fwName(fwId) + '：' + resLabel(fwId, r.primary) + ' / ' + resLabel(fwId, r.secondary);
      var line = wrapText(txt, ffs, colW - 24, 1)[0] || txt;
      var p = pillLeft(x0, y + ffs, line, pal.card, pal.accent, ffs);
      out += p.svg;
      y += ffs + 16 + 10;
    });

    out += '<line x1="' + x0 + '" y1="' + (H - 76) + '" x2="' + (x0 + colW) + '" y2="' + (H - 76) + '" stroke="' + pal.sub + '" stroke-opacity="0.32" stroke-width="1"/>';
    out += '<text x="' + x0 + '" y="' + (H - 44) + '" font-size="17" fill="' + pal.sub + '">打开链接，测出属于你的那一版审美 →</text>';
    out += '</svg>';
    return out;
  }

  /*
   * 竖版故事图：1080×1920（朋友圈 / 小红书 / IG Story 的保存尺寸）
   * ----------------------------------------------------------------
   * 直接把 800×1130 的主海报作为嵌套 <svg> 等比放进画面中部，避免重复维护一套布局；
   * 内层的渐变 id 需改名，否则与外层背景的 id 冲突（SVG 里 id 必须全文档唯一）。
   */
  function renderStorySVG(opts) {
    opts = opts || {};
    var theme = pickTheme(opts);
    var pal = pickPalette(opts.vector || {}, theme);
    var W = 1080, H = 1920;

    var inner = renderPosterSVG(opts)
      .replace(/id="bg"/g, 'id="cardbg"')
      .replace(/url\(#bg\)/g, 'url(#cardbg)')
      .replace(/^<svg[^>]*>/, '<svg x="40" y="250" width="1000" height="1412.5" viewBox="0 0 800 1130" preserveAspectRatio="xMidYMid meet">');

    var out = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '" font-family="-apple-system,Helvetica,Arial,sans-serif">';
    out += '<defs><linearGradient id="stbg" x1="0" y1="0" x2="0.3" y2="1">' +
      '<stop offset="0" stop-color="' + pal.bg2 + '"/><stop offset="1" stop-color="' + pal.bg1 + '"/></linearGradient></defs>';
    out += '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="url(#stbg)"/>';
    out += '<text x="' + (W / 2) + '" y="140" font-size="34" font-weight="700" fill="' + pal.ink + '" text-anchor="middle" letter-spacing="4">AI 审美系统</text>';
    out += '<text x="' + (W / 2) + '" y="192" font-size="22" fill="' + pal.sub + '" text-anchor="middle" letter-spacing="6">神 性 测 评</text>';
    out += inner;
    out += '<text x="' + (W / 2) + '" y="1760" font-size="30" font-weight="700" fill="' + pal.ink + '" text-anchor="middle">你的审美，也值得被看见</text>';
    var link = wrapText(opts.url || '', 22, W - 160, 1)[0] || '';
    if (link) out += '<text x="' + (W / 2) + '" y="1818" font-size="22" fill="' + pal.sub + '" text-anchor="middle">' + esc(link) + '</text>';
    out += '</svg>';
    return out;
  }

  // SVG -> PNG（自包含、无外部资源，canvas 不会污染）
  function svgToPng(svg, w, h, cb) {
    try {
      var blob = new Blob([svg], { type: 'image/svg+xml;charset=utf-8' });
      var url = URL.createObjectURL(blob);
      var img = new Image();
      img.onload = function () {
        try {
          var c = document.createElement('canvas');
          c.width = w; c.height = h;
          var ctx = c.getContext('2d');
          ctx.drawImage(img, 0, 0, w, h);
          c.toBlob(function (b) { URL.revokeObjectURL(url); cb(b); }, 'image/png');
        } catch (e) { URL.revokeObjectURL(url); cb(null); }
      };
      img.onerror = function () { URL.revokeObjectURL(url); cb(null); };
      img.src = url;
    } catch (e) { cb(null); }
  }

  // svg -> PNG dataURL（用于随分享请求一起上传给服务端落盘）
  function svgToPngDataURL(svg, w, h, cb) {
    svgToPng(svg, w, h, function (blob) {
      if (!blob) return cb(null);
      try {
        var fr = new FileReader();
        fr.onload = function () { cb(String(fr.result || '') || null); };
        fr.onerror = function () { cb(null); };
        fr.readAsDataURL(blob);
      } catch (e) { cb(null); }
    });
  }

  window.AestheticPoster = {
    renderPosterSVG: renderPosterSVG,
    renderOGCardSVG: renderOGCardSVG,
    renderStorySVG: renderStorySVG,
    svgToPng: svgToPng,
    svgToPngDataURL: svgToPngDataURL,
    PALETTES: PALETTES
  };
})();
